@import url('/static/vendor/css/fonts.css?v=2026.07.25.1.1785206114');

        /* 本地 Tailwind 工具类兜底：CDN 慢/未就绪时也能立刻给图标尺寸，避免首屏左侧栏空白 */
        .w-1\.5 { width: 0.375rem; }
        .h-1\.5 { height: 0.375rem; }
        .w-4 { width: 1rem; }
        .h-4 { height: 1rem; }
        .w-5 { width: 1.25rem; }
        .h-5 { height: 1.25rem; }
        .flex-shrink-0 { flex-shrink: 0; }
        .rounded-full { border-radius: var(--ui-radius-pill); }
        .mb-12 { margin-bottom: var(--ui-space-10); }
        .transition-colors { transition-property: color, background-color, border-color, fill, stroke; transition-duration: var(--ui-motion-duration-fast); transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); }
        .animate-pulse { animation: studio-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        @keyframes studio-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .5; } }

        /* 极简滚动条 */
        html,
        body {
            overscroll-behavior: auto;
            height: 100%;
            overflow: hidden;
        }

        *::-webkit-scrollbar {
            width: 10px !important;
            height: 10px !important;
            background: transparent !important;
        }

        *::-webkit-scrollbar-track {
            background: transparent !important;
            border: none !important;
        }

        *::-webkit-scrollbar-thumb {
            background-color: var(--ui-color-border-primary) !important;
            border: var(--ui-border-width-strong) solid transparent !important;
            border-right-width: var(--ui-border-width-strong) !important;
            background-clip: padding-box !important;
            border-radius: var(--ui-radius-s) !important;
            min-height: 36px;
        }

        *::-webkit-scrollbar-thumb:hover {
            background-color: var(--ui-color-text-tertiary) !important;
        }

        *::-webkit-scrollbar-corner {
            background: transparent !important;
        }

        * {
            scrollbar-width: thin !important;
            scrollbar-color: var(--ui-color-border-primary) transparent !important;
        }

        body {
            background: var(--ui-color-surface-canvas);
            font-family: var(--ui-font-sans);
            overflow: hidden;
            height: 100vh;
            color: var(--ui-color-text-primary);
            transition: background var(--ui-motion-duration-slow), color var(--ui-motion-duration-slow);
        }

        .app-shell {
            display: flex;
            width: 100%;
            height: 100vh;
            background: var(--ui-color-surface-canvas);
            position: relative;
            transition: background var(--ui-motion-duration-slow);
        }

        /* 侧边栏 */
        .sidebar {
            width: 80px;
            min-width: 80px;
            height: 100vh;
            max-height: 100vh;
            background: var(--ui-color-surface-canvas);
            display: flex;
            flex-direction: column;
            align-items: center;
            border-right: var(--ui-border-width-thin) solid var(--ui-color-border-secondary);
            padding: var(--ui-space-10) var(--ui-space-0);
            transition: width var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid), background var(--ui-motion-duration-slow), border-color var(--ui-motion-duration-slow);
            z-index: 50;
            overflow: hidden;
        }

        body.studio-scale-host .sidebar {
            height: calc(100vh / var(--studio-ui-scale, 1));
            max-height: calc(100vh / var(--studio-ui-scale, 1));
            zoom: var(--studio-ui-scale, 1);
        }

        /* 首次加载时与 iframe 的 0.5s 淡入同步播放，避免侧栏"焊死"在原地造成视觉断层 */
        @keyframes sidebar-enter {
            from { opacity: 0; transform: translateX(-6px); }
            to { opacity: 1; transform: translateX(0); }
        }
        html:not(.studio-route-booting) .sidebar {
            animation: sidebar-enter 0.5s var(--ui-motion-ease-fluid);
        }

        .logo-ring {
            width: 36px;
            height: 36px;
            border: var(--ui-border-width-strong) solid var(--ui-color-text-primary);
            border-radius: var(--ui-radius-s);
            background: transparent;
            padding: var(--ui-space-0);
            color: var(--ui-color-text-primary);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            flex: 0 0 auto;
            transition: transform var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid), border-radius var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid), border-color var(--ui-motion-duration-slow), background-color var(--ui-motion-duration-normal), box-shadow var(--ui-motion-duration-normal);
        }

        .logo-ring:hover,
        .logo-ring:focus-visible {
            background: var(--ui-color-action-tertiary-hover);
            border-color: var(--ui-color-text-primary);
            box-shadow: 0 0 0 4px rgba(148, 163, 184, .16), 0 10px 24px rgba(15, 23, 42, .08);
            outline: none;
        }

        .logo-ring:hover #logo-dot,
        .logo-ring:focus-visible #logo-dot {
            transform: scale(1.8);
        }

        .logo-ring:active {
            transform: scale(.94);
            transition-delay: 0s;
        }

        #logo-dot {
            transition: transform var(--ui-motion-duration-fast) var(--ui-motion-ease-standard), background-color var(--ui-motion-duration-fast) var(--ui-motion-ease-standard), box-shadow var(--ui-motion-duration-fast) var(--ui-motion-ease-standard);
        }

        /* 导航项 */
        .nav-item {
            position: relative;
            width: 48px;
            height: 48px;
            flex: 0 0 48px;
            margin: var(--ui-space-2) var(--ui-space-0);
            display: flex;
            align-items: center;
            justify-content: flex-start;
            border-radius: var(--ui-radius-l);
            cursor: pointer;
            transition: width var(--ui-motion-duration-slow) var(--ui-motion-ease-fluid);
            color: var(--ui-color-text-tertiary);
            overflow: hidden;
            padding-left: var(--ui-space-3);
        }

        .nav-item:hover {
            background: var(--ui-color-action-tertiary-hover);
            color: var(--ui-color-text-primary);
        }

        .nav-item.active {
            background: var(--ui-color-action-primary);
            color: var(--ui-color-text-on-action-primary);
        }

        html.theme-dark .nav-item.active,
        body.theme-dark .nav-item.active {
            background: var(--ui-color-action-secondary-selected);
            color: var(--ui-color-text-primary);
        }

        .nav-text {
            opacity: 0;
            margin-left: var(--ui-space-4);
            font-weight: var(--ui-font-weight-medium);
            font-size: var(--ui-font-size-3);
            white-space: nowrap;
            transition: opacity var(--ui-motion-duration-slow);
        }

        .nav-fold-toggle {
            position: relative;
            width: 48px;
            height: var(--ui-control-height-s);
            flex: 0 0 36px;
            margin: var(--ui-space-0) var(--ui-space-0) var(--ui-space-1);
            padding-left: var(--ui-space-3);
            border: var(--ui-border-width-thin) solid var(--ui-color-border-secondary);
            border-radius: var(--ui-radius-l);
            background: transparent;
            color: var(--ui-color-text-tertiary);
            display: flex;
            align-items: center;
            justify-content: flex-start;
            cursor: pointer;
            overflow: hidden;
            transition: width var(--ui-motion-duration-slow) var(--ui-motion-ease-fluid), background-color var(--ui-motion-duration-normal), color var(--ui-motion-duration-normal), border-color var(--ui-motion-duration-normal);
        }

        .nav-fold-toggle:hover {
            background: var(--ui-color-action-tertiary-hover);
            color: var(--ui-color-text-primary);
            border-color: var(--ui-color-border-primary);
        }

        .nav-fold-icon {
            width: var(--ui-icon-size-s);
            height: var(--ui-icon-size-s);
            flex: 0 0 auto;
            transition: transform var(--ui-motion-duration-normal) var(--ui-motion-ease-fluid);
        }

        .nav-fold-toggle[aria-expanded="false"] .nav-fold-icon {
            transform: rotate(-90deg);
        }

        .nav-fold-group {
            width: 100%;
            flex: 0 0 auto;
            max-height: 720px;
            opacity: 1;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            align-items: center;
            transition: max-height var(--ui-motion-duration-slow) var(--ui-motion-ease-fluid), opacity var(--ui-motion-duration-normal) var(--ui-motion-ease-standard);
        }

        .nav-fold-group.is-collapsed {
            max-height: 0;
            opacity: 0;
            pointer-events: none;
        }

        .sidebar nav {
            width: 100%;
            min-height: 0;
            flex: 1 1 auto;
            overflow-y: auto;
            overflow-x: hidden;
            display: flex;
            flex-direction: column;
            align-items: center;
            padding: var(--ui-space-0) var(--ui-space-0) var(--ui-space-1);
            overscroll-behavior: contain;
            scrollbar-gutter: stable;
            -webkit-overflow-scrolling: touch;
            scrollbar-width: thin;
            scrollbar-color: rgba(148, 163, 184, .34) transparent;
        }

        .sidebar::-webkit-scrollbar { width: 4px !important; }
        .sidebar::-webkit-scrollbar-track { background: transparent !important; }
        .sidebar::-webkit-scrollbar-thumb {
            background: var(--ui-color-surface) !important;
            border: var(--ui-border-width-none) !important;
            border-radius: var(--ui-radius-pill) !important;
        }

        .sidebar nav::-webkit-scrollbar { width: 4px !important; }
        .sidebar nav::-webkit-scrollbar-track { background: transparent !important; }
        .sidebar nav::-webkit-scrollbar-thumb {
            background: var(--ui-color-surface) !important;
            border: var(--ui-border-width-none) !important;
            border-radius: var(--ui-radius-pill) !important;
        }

        .sidebar nav > * {
            flex-shrink: 0;
        }

        /* 主舞台区 */
        .stage {
            flex: 1;
            background: var(--ui-color-surface-subtle);
            margin: var(--ui-space-4);
            border-radius: var(--ui-radius-l);
            overflow: hidden;
            border: var(--ui-border-width-thin) solid var(--ui-color-border-primary);
            position: relative;
            transition: background var(--ui-motion-duration-slow), border-color var(--ui-motion-duration-slow);
        }

        body.studio-scale-host .stage {
            margin: max(var(--ui-space-2), calc(var(--ui-space-4) * var(--studio-ui-scale, 1)));
            border-radius: max(var(--ui-radius-l), calc(var(--ui-radius-l) * var(--studio-ui-scale, 1)));
        }

        iframe {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            border: none;
            opacity: 0;
            transform: scale(1.02);
            filter: blur(4px);
            transition: all var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid);
            pointer-events: none;
        }

        iframe.active {
            opacity: 1;
            transform: scale(1);
            filter: blur(0);
            pointer-events: auto;
        }

        /* 左下角监视器 */
        .nano-monitor {
            position: absolute;
            bottom: 24px;
            left: 24px;
            z-index: 100;
            display: flex;
            align-items: center;
            gap: var(--ui-space-2);
            background: var(--ui-color-surface-floating);
            backdrop-filter: blur(12px);
            padding: var(--ui-space-2) var(--ui-space-3);
            border-radius: var(--ui-radius-s);
            border: var(--ui-border-width-thin) solid color-mix(in srgb, var(--ui-color-text-primary) 6%, transparent);
            box-shadow: var(--ui-shadow-none);
            font-family: var(--ui-font-mono);
            transition: all var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid);
        }

        .nano-monitor.is-busy {
            background: var(--ui-color-surface);
            color: var(--ui-color-text-primary);
            border-color: var(--ui-color-border-secondary);
            box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
        }

        .stat-group {
            display: flex;
            align-items: center;
            gap: var(--ui-space-2);
            font-size: var(--ui-font-size-2);
            font-weight: var(--ui-font-weight-bold);
            color: var(--ui-color-text-primary);
        }

        .stat-group:first-child {
            gap: var(--ui-space-2);
        }

        .nano-monitor.is-busy .stat-group {
            color: var(--ui-color-text-primary);
        }

        .divider {
            width: 1px;
            height: 12px;
            background: color-mix(in srgb, var(--ui-color-text-primary) 12%, transparent);
        }

        .is-busy .divider {
            background: var(--ui-color-surface);
        }

        .pulse-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--ui-color-surface);
            margin-right: var(--ui-space-0);
            flex: 0 0 auto;
        }

        .spinner-nano {
            width: 10px;
            height: 10px;
            border: var(--ui-border-width-strong) solid var(--ui-color-border-secondary);
            border-top-color: #fff;
            border-radius: 50%;
            animation: spin 0.8s linear infinite;
            display: none;
        }

        .is-busy .spinner-nano { display: block; }
        .is-busy .pulse-dot { display: none; }

        @keyframes spin {
            to { transform: rotate(360deg); }
        }

        .label-nano {
            text-transform: uppercase;
            letter-spacing: var(--ui-letter-spacing-normal);
            opacity: 0.5;
            font-size: var(--ui-font-size-1);
        }

        /* 作者组件 */
        .author-box {
            width: 100%;
            height: 60px;
            flex: 0 0 60px;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
        }

        .dx-letter {
            position: absolute;
            font-size: var(--ui-font-size-3);
            font-weight: var(--ui-font-weight-bold);
            color: var(--ui-color-text-primary);
            /* 只过渡 hover 时真正改的 transform/opacity，避免 all 触发延迟 */
            transition: transform var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid) var(--ui-motion-duration-deliberate), opacity var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid) var(--ui-motion-duration-deliberate);
            z-index: 10;
        }

        .letter-d { transform: translateX(-8px); }
        .letter-x { transform: translateX(8px); }

        .author-content-wrap {
            display: flex;
            flex-direction: column;
            align-items: center;
            opacity: 0;
            transform: scale(0.9);
            transition: all var(--ui-motion-duration-deliberate) var(--ui-motion-ease-fluid) 0s;
            pointer-events: none;
        }

        .author-name-lite {
            font-size: var(--ui-font-size-2);
            font-weight: var(--ui-font-weight-bold);
            margin-bottom: var(--ui-space-2);
            color: var(--ui-color-text-primary);
        }

        .social-row-lite { display: flex; gap: var(--ui-space-3); }

        .social-icon-lite {
            color: var(--ui-color-text-tertiary);
            transition: color var(--ui-motion-duration-normal), transform var(--ui-motion-duration-normal);
        }

        .social-icon-lite:hover {
            color: var(--ui-color-text-primary);
            transform: translateY(-1px);
        }

        .side-actions {
            margin-top:auto;
            margin-bottom:var(--ui-space-3);
            display:flex;
            flex-direction:column;
            align-items:center;
            gap:var(--ui-space-2);
            width:100%;
            flex:0 0 auto;
        }

        .side-actions-primary {
            width:100%;
            display:flex;
            flex-direction:column;
            align-items:center;
            gap:var(--ui-space-2);
        }

        .side-utility-row {
            display:flex;
            flex-direction:column;
            align-items:center;
            justify-content:center;
            gap:var(--ui-space-2);
            width:100%;
        }

        .sidebar.is-pinned .side-utility-row {
            flex-direction:row;
        }

        .side-icon-button {
            width:var(--ui-icon-size-l);
            height:var(--ui-icon-size-l);
            padding:var(--ui-space-0);
            border:var(--ui-border-width-none);
            border-radius:var(--ui-radius-s);
            background:transparent;
            color:var(--ui-color-text-tertiary);
            display:flex;
            align-items:center;
            justify-content:center;
            cursor:pointer;
            transition:background-color var(--ui-motion-duration-normal), color var(--ui-motion-duration-normal), transform var(--ui-motion-duration-normal);
        }

        .side-icon-button svg {
            width:var(--ui-icon-size-s);
            height:var(--ui-icon-size-s);
        }

        .language-status-icon {
            min-width: 16px;
            font-size: var(--ui-font-size-2);
            font-weight: var(--ui-font-weight-bold);
            line-height: var(--ui-line-height-tight);
            text-align: center;
        }

        .side-icon-button:hover,
        .side-icon-button:focus-visible {
            background:var(--ui-color-action-tertiary-hover);
            color:var(--ui-color-text-primary);
            outline:none;
        }

        .side-icon-button:active {
            transform:scale(.94);
        }

        .side-pill {
            width:44px;
            height:var(--ui-control-height-s);
            border-radius:var(--ui-radius-pill);
            background: transparent;
            border: var(--ui-border-width-thin) solid var(--ui-color-border-secondary);
            color: var(--ui-color-text-tertiary);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: width var(--ui-motion-duration-slow) var(--ui-motion-ease-fluid), gap var(--ui-motion-duration-slow) var(--ui-motion-ease-fluid), background-color var(--ui-motion-duration-normal), color var(--ui-motion-duration-normal), border-color var(--ui-motion-duration-normal);
            flex-shrink: 0;
            overflow:hidden;
            gap:var(--ui-space-2);
            position:relative;
        }

        .side-pill:hover {
            background: var(--ui-color-action-tertiary-hover);
            color: var(--ui-color-text-primary);
            border-color: var(--ui-color-border-primary);
        }

        .side-pill.active {
            background: var(--ui-color-text-primary);
            color: var(--ui-color-text-on-action-primary);
            border-color: var(--ui-color-text-primary);
        }

        .side-pill.update-available {
            border-color:var(--ui-color-border-secondary);
            color:var(--ui-color-text-primary);
            overflow:visible;
        }

        html.theme-dark .side-pill.update-available,
        body.theme-dark .side-pill.update-available {
            border-color:var(--ui-color-border-secondary);
            color:var(--ui-color-text-on-action-primary);
        }

        .side-pill.update-available::after {
            content:"NEW";
            position:absolute;
            top:-7px;
            right:-9px;
            min-width:28px;
            height:var(--ui-control-height-xs);
            padding:var(--ui-space-0) var(--ui-space-1);
            border-radius:var(--ui-radius-pill);
            background:var(--ui-color-surface);
            display:flex;
            align-items:center;
            justify-content:center;
            color:var(--ui-color-text-on-action-primary);
            font-size:var(--ui-font-size-1);
            font-weight:var(--ui-font-weight-bold);
            letter-spacing:var(--ui-letter-spacing-normal);
            box-shadow:0 6px 16px rgba(34,197,94,.28), 0 0 0 3px rgba(34,197,94,.12);
            pointer-events:none;
        }

        html.theme-dark .side-pill.update-available::after,
        body.theme-dark .side-pill.update-available::after {
            background:var(--ui-color-surface-canvas);
            color:var(--ui-color-text-primary);
            box-shadow:0 6px 16px rgba(74,222,128,.22), 0 0 0 3px rgba(74,222,128,.12);
        }

        .side-pill svg { width: var(--ui-icon-size-s); height: var(--ui-icon-size-s); flex:0 0 auto; }
        /* 与智能画布节点右键菜单共用同一套菜单结构和视觉规格。 */
        .sidebar-settings-menu.smart-node-context-menu {
            position:fixed;
            z-index:var(--ui-z-modal);
            display:none;
            width:244px;
            max-width:calc(100vw - 20px);
            max-height:min(620px, calc(100vh - 20px));
            padding:var(--ui-space-1);
            overflow:auto;
            border:var(--ui-border-width-thin) solid var(--ui-color-border-secondary);
            border-radius:var(--ui-radius-l);
            background:var(--ui-color-surface-floating);
            color:var(--ui-color-text-primary);
            box-shadow:var(--ui-shadow-overlay);
            backdrop-filter:blur(20px);
            scrollbar-width:thin;
        }
        .sidebar-settings-menu.smart-node-context-menu.open { display:block; }
        .sidebar-settings-menu .smart-context-menu-section { padding:var(--ui-space-1) var(--ui-space-0); }
        .sidebar-settings-menu .smart-context-menu-section + .smart-context-menu-section { border-top:var(--ui-border-width-thin) solid var(--ui-color-border-secondary); }
