            width:100%;
            min-height:34px;
            padding:var(--ui-space-2) var(--ui-space-2);
            border:var(--ui-border-width-none);
            border-radius:var(--ui-radius-s);
            display:grid;
            grid-template-columns:18px minmax(0, 1fr) auto;
            align-items:center;
            gap:var(--ui-space-2);
            background:transparent;
            color:var(--ui-color-text-primary);
            text-align:left;
            font:inherit;
            font-size:var(--ui-font-size-2);
            line-height:var(--ui-line-height-tight);
            cursor:pointer;
        }
        .sidebar-settings-menu .smart-context-menu-item:hover,
        .sidebar-settings-menu .smart-context-menu-item:focus-visible,
        .sidebar-settings-menu .smart-context-menu-item.active {
            outline:var(--ui-border-width-none);
            background:var(--ui-color-surface-subtle);
        }
        .sidebar-settings-menu .smart-context-menu-item svg {
            width:var(--ui-icon-size-s);
            height:var(--ui-icon-size-s);
            color:var(--ui-color-text-tertiary);
            stroke-width:2;
        }
        .sidebar-settings-menu .smart-context-menu-item > span {
            min-width:0;
            overflow:hidden;
            text-overflow:ellipsis;
            white-space:nowrap;
        }
        .sidebar-settings-menu .smart-context-menu-item kbd {
            padding:var(--ui-space-0);
            border:var(--ui-border-width-none);
            background:transparent;
            color:var(--ui-color-text-tertiary);
            box-shadow:var(--ui-shadow-overlay);
            font:inherit;
            font-size:var(--ui-font-size-1);
            font-weight:var(--ui-font-weight-bold);
            white-space:nowrap;
        }
        .sidebar-settings-menu .update-now-btn {
            width:100%;
            min-height:var(--ui-control-height-s);
